import subprocess, time, re

def tmux(*args):
    subprocess.run(["tmux"]+list(args), capture_output=True)
def cap_plain_and_sel():
    r=subprocess.run(["tmux","capture-pane","-t","test","-p","-e"], capture_output=True, text=True)
    lines=r.stdout.splitlines()
    sel=None
    for l in lines:
        if '\x1b[7m' in l:
            # strip ansi
            plain=re.sub(r'\x1b\[[0-9;]*m','',l)
            sel=plain.strip()
    plain_lines=[re.sub(r'\x1b\[[0-9;]*m','',l) for l in lines]
    return sel, plain_lines
def show(label):
    sel,pl=cap_plain_and_sel()
    print(f"{label:20} sel={sel!r}")
def key(k, wait=0.3):
    tmux("send-keys","-t","test",k); time.sleep(wait)
def start(json_str, args=""):
    open("/tmp/case.json","w").write(json_str)
    tmux("kill-session","-t","test"); time.sleep(0.25)
    tmux("new-session","-d","-s","test","-x","80","-y","24")
    tmux("send-keys","-t","test",f"./executable {args} /tmp/case.json","Enter"); time.sleep(0.7)

start('{"name":"Alice","age":30,"active":true,"tags":["a","b"],"nested":{"x":1,"y":null}}')
