import os,pty,select,time,signal
def test(label,send=None,sig=None):
 pid,fd=pty.fork()
 if pid==0:
  os.execv('./executable',['./executable','/tmp/case.json'])
 time.sleep(.6)
 # drain
 while select.select([fd],[],[],0)[0]:
