import subprocess,time,re
def tmux(*a): return subprocess.run(["tmux"]+list(a),capture_output=True,text=True)
def sel():
 out=[]
 for l in tmux('capture-pane','-t','test','-p','-e').stdout.splitlines():
  if '\x1b[7m' in l: out.append(re.sub(r'\x1b\[[0-9;]*m','',l).strip())
 return out
