for seq in [['Down'],['Up'],['Enter'],['+'],['-'],['G'],['g','g'],['Tab'],['PageDown'],['PageUp'],['Right'],['Space']]:
 start('{"a":1,"b":2}'); key('Down'); key('-'); show('hidden after scalar -')
 for k in seq: key(k)
 show('then '+' '.join(seq))
 key('q'); time.sleep(.15)
 # if q didn't exit due hidden? force kill next start
