                intpart = digits[:exp+1]
                frac = digits[exp+1:]
            else:
                intpart = digits + "0" * (exp + 1 - len(digits))
                frac = ""
            return sign + intpart + "." + (frac if frac else "0")
        else:
            return sign + "0." + "0" * (-exp - 1) + digits
    else:
