def format_double(x):
    if x == 0.0:
        return "-0.0" if math.copysign(1.0, x) < 0 else "0.0"
    sign = "-" if x < 0 else ""
    d = Decimal(repr(abs(x)))
    tup = d.as_tuple()
    digits = "".join(str(v) for v in tup.digits)
    exp = d.adjusted()  # value = digits[0].digits[1:] * 10**exp
    digits = digits.rstrip("0") or "0"
    if -4 <= exp <= 14:
        if exp >= 0:
            if len(digits) > exp + 1:
                intpart = digits[:exp+1]
                frac = digits[exp+1:]
            else:
                intpart = digits + "0" * (exp + 1 - len(digits))
                frac = ""
            return sign + intpart + "." + (frac if frac else "0")
        else:
            return sign + "0." + "0" * (-exp - 1) + digits
    else:
        mant = digits[0] + ("." + digits[1:] if len(digits) > 1 else "")
        return sign + mant + "e" + ("+" if exp >= 0 else "-") + str(abs(exp)).rjust(2, "0")

