# ---------------------------------------------------------------------------
# Terminal text utilities
# ---------------------------------------------------------------------------

ST_DEFAULT = "default"; ST_KEY = "key"; ST_STRING = "string"; ST_NUMBER = "number"
ST_BOOL = "bool"; ST_NULL = "null"; ST_GRAY = "gray"; ST_CONTAINER = "container"

def is_cc(ch):
    return unicodedata.category(ch) == "Cc"

def sanitize_text(s):
    return "".join(ch for ch in s if not is_cc(ch) and ch not in "\u2028\u2029")

def sanitize_paragraph(s):
    out = []
    for ch in s:
        if ch in ("\u2028", "\u2029", "\n"):
            out.append("\n")
        elif is_cc(ch):
            continue
        else:
            out.append(ch)
    return "".join(out)

def grapheme_clusters(s):
    clusters = []
    for ch in s:
        if not clusters:
            clusters.append(ch); continue
        prev = clusters[-1]
        join = False
        if unicodedata.combining(ch) or unicodedata.category(ch) in ("Mn", "Me", "Mc"):
            join = True
        elif ch in "\ufe0f\ufe0e" or (0xFE00 <= ord(ch) <= 0xFE0F) or (0xE0100 <= ord(ch) <= 0xE01EF):
            join = True
        elif 0x1F3FB <= ord(ch) <= 0x1F3FF:
            join = True
        elif ch == "\u200d" or prev.endswith("\u200d"):
            join = True
        elif 0x1F1E6 <= ord(ch) <= 0x1F1FF and len(prev) == 1 and 0x1F1E6 <= ord(prev) <= 0x1F1FF:
            join = True
        if join:
            clusters[-1] = prev + ch
        else:
            clusters.append(ch)
    return clusters

def cluster_width(cl):
    if not cl:
        return 0
    # Two regional indicators form a flag.
    if len(cl) >= 2 and all(0x1F1E6 <= ord(c) <= 0x1F1FF for c in cl):
        return 2
    for ch in cl:
        if unicodedata.east_asian_width(ch) in ("W", "F"):
            return 2
        if 0x1F300 <= ord(ch) <= 0x1FAFF or 0x2600 <= ord(ch) <= 0x27BF:
            # Many pictographs are wide in terminals; common text symbols
            # in the second range are usually single-width unless the
            # east-asian check above returned wide.
            if ord(ch) >= 0x1F300:
                return 2
    # If cluster only consists of combining / zero-width codepoints.
    if all(unicodedata.combining(c) or unicodedata.category(c) in ("Mn", "Me", "Mc") or c in "\u200b\u200d\ufeff" for c in cl):
        return 0
    return 1

def text_width(s):
    return sum(cluster_width(c) for c in grapheme_clusters(s))

def segments_width(segs):
    return sum(text_width(t) for t, _st, _f in segs)

def clip_segments(segs, width):
    if width <= 0:
        return [], 0
    out = []; w = 0
    for text, style, focus in segs:
        buf = ""
        for cl in grapheme_clusters(text):
            cw = cluster_width(cl)
            if cw == 0:
                buf += cl; continue
            if w + cw > width:
                if buf:
                    out.append((buf, style, focus))
                if w < width:
                    out.append((" " * (width - w), style, focus))
                return out, width
            buf += cl; w += cw
        if buf:
            out.append((buf, style, focus))
    return out, w

def pad_segments(segs, width, fill_style=ST_DEFAULT, fill_focus=None):
    clipped, w = clip_segments(segs, width)
    if w < width:
        clipped.append((" " * (width - w), fill_style, fill_focus))
    return clipped

class Block:
    __slots__ = ("rows", "width", "focus_boxes", "blank_row", "pad_style", "pad_focus")
    def __init__(self, rows, width, focus_boxes=None, blank_row=None, pad_style=ST_DEFAULT, pad_focus=None):
        self.rows = rows; self.width = width
        self.focus_boxes = focus_boxes or {}
        self.pad_style = pad_style; self.pad_focus = pad_focus
        if blank_row is None:
            blank_row = [(" " * width, ST_DEFAULT, None)] if width else []
        self.blank_row = blank_row
    @property
    def height(self):
        return len(self.rows)

def shift_boxes(boxes, dx, dy):
    out = {}
    for k, (x, y, w, h) in boxes.items():
        out[k] = (x + dx, y + dy, w, h)
    return out

def merge_boxes(dst, src):
    for k, v in src.items():
        dst[k] = v

def text_block(text, style=ST_DEFAULT, focus=None, blank_style=None, blank_focus=None):
    text = sanitize_text(text)
    w = text_width(text)
    rows = [[(text, style, focus)] if text or w == 0 else []]
    if not text:
        rows = [[]]
    boxes = {}
    if focus is not None:
        boxes[focus] = (0, 0, w, 1)
    bs = style if blank_style is None else blank_style
    blank = [(" " * w, bs, blank_focus)] if w else []
    return Block(rows, w, boxes, blank)

def spacer_block(width, height=1, style=ST_DEFAULT):
    rows = [[(" " * width, style, None)] if width else [] for _ in range(max(1, height))]
    blank = [(" " * width, style, None)] if width else []
    return Block(rows, width, {}, blank)

def hbox(blocks):
    blocks = list(blocks)
    if not blocks:
        return Block([[]], 0)
    height = max(b.height for b in blocks)
    width = sum(b.width for b in blocks)
    rows = []
    boxes = {}
    offsets = []
    x = 0
    for b in blocks:
        offsets.append(x); x += b.width
    for y in range(height):
        row = []
        for b in blocks:
            if y < b.height:
                row.extend(b.rows[y])
            else:
                row.extend(b.blank_row)
        rows.append(pad_segments(row, width))
    for b, dx in zip(blocks, offsets):
        merge_boxes(boxes, shift_boxes(b.focus_boxes, dx, 0))
    blank = []
    for b in blocks:
        blank.extend(b.blank_row)
    blank = pad_segments(blank, width)
    return Block(rows, width, boxes, blank)

def vbox(blocks):
    blocks = list(blocks)
    if not blocks:
        return Block([[]], 0)
    width = max(b.width for b in blocks)
    rows = []; boxes = {}; y = 0
    for b in blocks:
        for r in b.rows:
            rows.append(pad_segments(r, width))
        merge_boxes(boxes, shift_boxes(b.focus_boxes, 0, y))
        y += b.height
    return Block(rows, width, boxes, [(" " * width, ST_DEFAULT, None)] if width else [])

def fit_block(block, width):
    rows = [pad_segments(r, width, block.pad_style, block.pad_focus) for r in block.rows]
    boxes = {}
    for k, (x, y, w, h) in block.focus_boxes.items():
        if x < width:
            boxes[k] = (x, y, min(w, width - x), h)
    blank = pad_segments(block.blank_row, width, block.pad_style, block.pad_focus)
    return Block(rows, width, boxes, blank, block.pad_style, block.pad_focus)

def paragraph_lines(text, width):
    # text already sanitised. Hard line breaks are '\n'.
    if width is not None and width <= 0:
        return [""]
    lines = []
    current = []; current_w = 0
    def finish():
        nonlocal current, current_w
        if current:
            lines.append(" ".join(current))
        current = []; current_w = 0
    hard_segments = text.split("\n")
    for si, segment in enumerate(hard_segments):
        if segment == "":
            continue
        words = segment.split(" ")
        for word in words:
            ww = text_width(word)
            cost = ww if not current else 1 + ww
            if width is not None and current and current_w + cost > width:
                finish(); cost = ww
            current.append(word); current_w += cost
        if si < len(hard_segments) - 1:
            finish()
    finish()
    return lines or [""]

def paragraph_block(text, style, focus, width):
    text = sanitize_paragraph(text)
    raw_lines = paragraph_lines(text, width)
    if width is None:
        bw = max((text_width(l) for l in raw_lines), default=0)
    else:
        bw = min(width, max((text_width(l) for l in raw_lines), default=0))
