# ---------------------------------------------------------------------------
# Rendering the JSON tree into blocks of styled segments
# ---------------------------------------------------------------------------

def node_focus(node):
    return ("node", node)
def toggle_focus(node):
    return ("toggle", node)

def table_eligible(node):
    return node.kind == "array" and len(node.children) >= 2 and all(c.kind == "object" for c in node.children)

def key_display(key, quoted=True):
    newlines = key.count("\n")
    cleaned = "".join(ch for ch in key if not is_cc(ch) and ch not in "\u2028\u2029")
    core = ('"' + cleaned + '"') if quoted else cleaned
    return core + " " * newlines

def scalar_style(node):
    return {"string": ST_STRING, "number": ST_NUMBER, "bool": ST_BOOL, "null": ST_NULL}.get(node.kind, ST_DEFAULT)

def make_prefix(indent, key):
    blocks = []
    if indent:
        blocks.append(spacer_block(indent))
    if key is not None:
        blocks.append(text_block(key_display(key, True), ST_KEY))
        blocks.append(text_block(": ", ST_DEFAULT))
    return blocks

def prefix_width(indent, key):
    return indent + (text_width(key_display(key, True)) + 2 if key is not None else 0)

def render_node(node, indent=0, key=None, comma=False, limit=None):
    if node.kind == "array" and node.table_view and table_eligible(node):
        return render_table_node(node, indent, key, limit)
    if not node.is_container():
        style = scalar_style(node)
        focus = node_focus(node)
        pw = prefix_width(indent, key)
        avail = None if limit is None else limit - pw - (1 if comma else 0)
        prefix_blocks = make_prefix(indent, key)
        if avail is not None and avail < 0:
            # The key itself overflows: show a truncated header line.
            para = paragraph_block("", style, focus, 0)
            blocks = prefix_blocks + [para]
            result = hbox(blocks)
        else:
            para = paragraph_block(node.display_text(), style, focus, avail)
            blocks = prefix_blocks + [para]
            if comma:
                blocks.append(text_block(",", ST_DEFAULT))
            result = hbox(blocks)
        result.pad_style = style; result.pad_focus = focus
        result.blank_row = [(" " * result.width, style, focus)] if result.width else []
        return result
    # Containers.
    focus = node_focus(node)
    eligible = table_eligible(node)
    if node.opened:
        token = "{" if node.kind == "object" else "["
    else:
        token = "{...}" if node.kind == "object" else "[...]"
    header_blocks = make_prefix(indent, key)
    header_blocks.append(text_block(token, ST_CONTAINER, focus, blank_style=ST_DEFAULT, blank_focus=None))
    if not node.opened and comma:
        header_blocks.append(text_block(",", ST_DEFAULT))
    if eligible:
        header_blocks.append(spacer_block(3))
        header_blocks.append(text_block("(table view)", ST_GRAY, toggle_focus(node)))
    header = hbox(header_blocks)
    if not node.opened:
        return header
    child_blocks = []
    if node.kind == "object":
        entries = node.children
        for idx, (k, child) in enumerate(entries):
            child_blocks.append(render_node(child, indent + 2, k, idx < len(entries) - 1, limit))
    else:
        for idx, child in enumerate(node.children):
            child_blocks.append(render_node(child, indent + 2, None, idx < len(node.children) - 1, limit))
    closing_char = "}" if node.kind == "object" else "]"
    closing_blocks = []
    if indent:
        closing_blocks.append(spacer_block(indent))
    closing_blocks.append(text_block(closing_char, ST_DEFAULT))
    if comma:
        closing_blocks.append(text_block(",", ST_DEFAULT))
