    total = sum(req_widths)
    if available >= total:
        return list(req_widths)
    if available <= 0 or total <= 0:
        return [0] * len(req_widths)
    widths = [int(r * available // total) for r in req_widths]
    rem = available - sum(widths)
    i = 0
