# ---------------------------------------------------------------------------
# Focus / interaction model
# ---------------------------------------------------------------------------

def table_columns(node):
    cols = []
    for row in node.children:
        for k, _c in row.children:
            if k not in cols:
                cols.append(k)
    return cols

def reset_subtree_normal(node):
    stack = [node]
    while stack:
        n = stack.pop()
        if n is not node:
            n.table_view = False
        if n.is_container():
            n.opened = (n.depth == 0) or (n.depth == 1 and n.kind == "object")
        n.endpoint = toggle_focus(n) if (n is node and n.table_view) else node_focus(n)
        stack.extend(n.child_nodes())

def reset_subtree_for_table(node):
    node.opened = True
    node.endpoint = toggle_focus(node)
    node.table_row_selected = [0] * len(node.children)
    for row in node.children:
        # Row objects are presented as fresh roots inside the table.
        stack = [(row, 0)]
        while stack:
            n, rel = stack.pop()
            n.table_view = False
            if n.is_container():
                n.opened = (rel == 0) or (rel == 1 and n.kind == "object")
            n.endpoint = node_focus(n)
            for c in n.child_nodes():
                stack.append((c, rel + 1))

class App:
    def __init__(self, root, fullscreen=False):
        self.root = root
        self.fullscreen = fullscreen
        self.focus = node_focus(root)
        self.pending_g = False
        self.quit = False
        self._init_endpoints(root)
        self.set_focus(node_focus(root), update_row=False)

    def _init_endpoints(self, root):
        stack = [root]
        while stack:
            n = stack.pop()
            n.endpoint = node_focus(n)
            if n.kind == "array":
                n.table_row_selected = [0] * len(n.children)
            stack.extend(n.child_nodes())

    # ---- utilities
    def walk_items(self, node, out=None):
        if out is None: out = []
        if node.kind == "array" and node.table_view and table_eligible(node):
            out.append(toggle_focus(node))
            cols = table_columns(node)
            for row in node.children:
                mapping = dict(row.children)
                for col in cols:
                    if col in mapping:
                        self.walk_items(mapping[col], out)
            return out
        out.append(node_focus(node))
        if node.is_container() and node.opened:
            for c in node.child_nodes():
                self.walk_items(c, out)
        return out

    def visible_items(self):
        return self.walk_items(self.root)

    def augmented_items(self):
        # Include siblings along the path to a focus that is currently
        # hidden under a closed ancestor.
        if self.focus[0] != "node":
            return self.visible_items()
        target = self.focus[1]
        ancestors = set()
        n = target.parent
        while n is not None:
            ancestors.add(id(n)); n = n.parent
        out = []
        def walk(node):
            if node.kind == "array" and node.table_view and table_eligible(node):
                out.append(toggle_focus(node)); return
            out.append(node_focus(node))
            if node.is_container() and (node.opened or id(node) in ancestors):
                for c in node.child_nodes(): walk(c)
        walk(self.root)
        return out

    def navigation_items(self):
        items = self.visible_items()
        if self.focus not in items and self.focus[0] == "node":
            aug = self.augmented_items()
            if self.focus in aug:
                return aug
        return items

