    def apply_plus(self, target):
        if not target.table_view and not target.opened:
            target.opened = True; return
        candidates = []
        stack = [(target, 0)]
        while stack:
            n, rel = stack.pop()
            if n is not target and n.is_container() and not n.opened and not n.table_view:
                candidates.append((rel, n))
            if n.opened or n.table_view:
                for c in n.child_nodes():
                    stack.append((c, rel + 1))
        if not candidates:
            return
        minrel = min(r for r, _n in candidates)
        for r, n in candidates:
            if r == minrel:
                n.opened = True

    def apply_minus(self, target):
        # Deepest reachable (through open ancestors) open container depth.
        deepest = target.depth
        stack = [target]
        while stack:
            n = stack.pop()
            if n.opened or n.table_view:
                if n.is_container():
                    deepest = max(deepest, n.depth)
                for c in n.child_nodes():
                    stack.append(c)
        stack = [target]
        while stack:
            n = stack.pop()
            if n.is_container() and n.depth >= deepest:
                n.opened = False
            for c in n.child_nodes():
                stack.append(c)

