    stack = [node]
    while stack:
        n = stack.pop()
        if n is not node:
            n.table_view = False
        if n.is_container():
            n.opened = (n.depth == 0) or (n.depth == 1 and n.kind == "object")
        n.endpoint = toggle_focus(n) if (n is node and n.table_view) else node_focus(n)
        stack.extend(n.child_nodes())

def reset_subtree_for_table(node):
