            n, rel = stack.pop()
            n.table_view = False
            if n.is_container():
                n.opened = (rel == 0) or (rel == 1 and n.kind == "object")
            n.endpoint = node_focus(n)
            for c in n.child_nodes():
                stack.append((c, rel + 1))

