# ---------------------------------------------------------------------------
# Screen output
# ---------------------------------------------------------------------------

FG_CODES = {ST_KEY: 94, ST_STRING: 92, ST_NUMBER: 96, ST_BOOL: 93, ST_NULL: 91, ST_GRAY: 90}

def style_tuple(style, focused):
    fg = FG_CODES.get(style)
    bold = (style == ST_CONTAINER and not focused)
    return (fg, bold, bool(focused))

def sgr_for(style):
    fg, bold, inv = style
    out = "\x1b[0m"
    if bold: out += "\x1b[1m"
    if inv: out += "\x1b[7m"
    if fg is not None: out += "\x1b[%dm" % fg
    return out

class Screen:
    def __init__(self, app, out_fd):
        self.app = app
        self.out_fd = out_fd
        self.prev_w = None; self.prev_h = None
        self.prev_fx = 0; self.prev_fy = 0
        self.origin_y = 0
        self.cell_focus = []
        self.output_broken = False

    def write(self, data):
        if self.output_broken:
            return
        if isinstance(data, str): data = data.encode("utf-8", "surrogateescape")
        try:
            view = memoryview(data)
            while view:
                n = os.write(self.out_fd, view)
                view = view[n:]
        except (BrokenPipeError, OSError):
            self.output_broken = True

    def terminal_size(self):
        try:
            sz = os.get_terminal_size(self.out_fd)
            if sz.columns > 0 and sz.lines > 0:
                return sz.columns, sz.lines
        except Exception:
            pass
        return 80, 24

    def build(self):
        app = self.app
        term_w, term_h = self.terminal_size()
        if app.fullscreen:
            view_w, view_h = term_w, term_h
            block = render_node(app.root, 0, None, False, view_w)
        else:
            unbounded = render_node(app.root, 0, None, False, None)
            req_w = max(1, unbounded.width)
            req_h = max(1, unbounded.height)
            view_w = min(term_w, req_w)
            view_h = min(term_h, req_h)
            block = unbounded if view_w >= req_w else render_node(app.root, 0, None, False, view_w)
        total_h = block.height
        focus_box = block.focus_boxes.get(app.focus)
        if focus_box and total_h > view_h:
            fx0, fy0, fw, fh = focus_box
            center_y = fy0 + fh // 2
            target_row = (view_h - 1) // 2
            offset = max(0, min(center_y - target_row, total_h - view_h))
        else:
            offset = 0
        seg_rows = block.rows[offset:offset + view_h]
        while len(seg_rows) < view_h:
            seg_rows.append([])
        # Convert to cells.
        grid = []        # (text, style) per cell; text '' for wide tail
        focus_grid = []
        default_style = style_tuple(ST_DEFAULT, False)
        for segs in seg_rows:
            cells = [(" ", default_style) for _ in range(view_w)]
            frow = [None] * view_w
            x = 0
            for text, style, fitem in segs:
                focused = (fitem is not None and fitem == app.focus)
                st = style_tuple(style, focused)
                for cl in grapheme_clusters(text):
                    cw = cluster_width(cl)
                    if cw == 0:
                        if x > 0:
                            txt, sty = cells[x - 1]
                            cells[x - 1] = (txt + cl, sty)
                        continue
                    if x + cw > view_w:
                        x = view_w
