            fx = max(0, min(focus_box[0], max(0, view_w - 1)))
            fy = max(0, min(focus_box[1] - offset, max(0, view_h - 1)))
        else:
            fx = 0; fy = 0
        return grid, focus_grid, view_w, view_h, fx, fy

    def draw(self, first=False):
        grid, focus_grid, view_w, view_h, fx, fy = self.build()
        self.cell_focus = focus_grid
