    def flush_escape(self):
        if bytes(self.buf) == b"\x1b":
            self.buf = bytearray()
            return ["escape"]
        if self.buf.startswith(b"\x1b") and len(self.buf) > 1:
            # Drop incomplete escape sequences after a timeout.
            self.buf = bytearray()
        return []
    def _parse(self, events):
        while self.buf:
            b = self.buf[0]
            if b == 0x1B:
                if len(self.buf) == 1:
                    return
