# ---------------------------------------------------------------------------
# Event loop and main
# ---------------------------------------------------------------------------

_signal_quit = False
_resize_flag = False

def _sig_quit(signum, frame):
    global _signal_quit
    _signal_quit = True

def _sig_resize(signum, frame):
    global _resize_flag
    _resize_flag = True

def query_cursor_row(in_fd, out_fd, parser):
    try:
        if not (os.isatty(in_fd) and os.isatty(out_fd)):
            return 0
        if os.fstat(in_fd).st_rdev != os.fstat(out_fd).st_rdev:
            return 0
    except Exception:
        return 0
    try:
        os.write(out_fd, b"\x1b[6n")
    except Exception:
        return 0
    buf = bytearray()
    row = 0
    import time
    deadline = time.time() + 0.12
    while time.time() < deadline:
        try:
            r, _w, _x = select.select([in_fd], [], [], max(0, deadline - time.time()))
        except Exception:
            break
        if not r:
            break
        try:
            data = os.read(in_fd, 4096)
        except Exception:
            break
        if not data:
            break
        buf += data
        m = re.search(br"\x1b\[(\d+);(\d+)R", bytes(buf))
        if m:
            row = max(0, int(m.group(1)) - 1)
            del buf[m.start():m.end()]
            break
    if buf:
        parser.buf = bytearray(buf) + parser.buf
    return row

